            reportPerm.query();
            if (reportPerm.next()) {
//                 gs.addInfoMessage(gs.getMessage("Report {0} is already shared with user {1}", [reportPerm.getDisplayValue("report_id"), reportPerm.getDisplayValue("user_id")]));
            } else {
                reportPerm.newRecord();
